"""CST LIR partial reassignment, generated by Create Migration Job and Assignment Management alike.

Steps per CST record that overlaps subnets being sent:
  1. UpdateLIR to Unassigned (only if the record is assigned)
  2. DeleteLIR (Transaction ID retired)
  3. SendLIR the reassigned portion(s)
  4. SendLIR the remaining portion(s)
All partial reassignments of a migration job live in ONE batch; each is a chain whose steps wait
only for the previous step of the same chain.
"""
import csv
import json
import shutil
import tempfile
import unittest
from io import StringIO
from ipaddress import ip_network
from pathlib import Path

import backend.main as app
from backend.tests.test_bulk_assignment_release import HEADER, business_row

ROOT = "87.101.190.0/24"
CONTAINER = "87.101.190.112/28"
ASSIGNED = "87.101.190.120/29"


def find_value(value, key):
    if isinstance(value, dict):
        if key in value:
            return value[key]
        for item in value.values():
            found = find_value(item, key)
            if found is not None:
                return found
    elif isinstance(value, list):
        for item in value:
            found = find_value(item, key)
            if found is not None:
                return found
    return None


class CstPartialReassignmentTest(unittest.TestCase):
    def setUp(self):
        self.temp_dir = Path(tempfile.mkdtemp())
        self.original_db_path = app.DB_PATH
        app.DB_PATH = self.temp_dir / "ipam.test.db"
        app.init_db()
        self.calls: list[tuple[str, str, str, int | None]] = []
        self.reject: set[tuple[str, str]] = set()  # (operation, cidr) pairs CST rejects

        def record(operation, cidr, transaction_id, status_id):
            self.calls.append((operation, cidr, transaction_id, status_id))
            if (operation, cidr) in self.reject:
                return "FAILED", f"CST {operation} rejected"
            return "SUCCESS", ""

        def fake_job(connection, config, resource, operation, payload, transaction_id):
            status, error = record(operation, resource.cidr, transaction_id, resource.assignment_status_id)
            return status, error, {"accepted": status == "SUCCESS", "externalApiCalled": True}

        def fake_http(config, method, url, headers, body, timeout):
            """Jobs pushed for a CST record with no local subnet go straight to HTTP."""
            payload = json.loads(body or b"{}")
            operation = "DELETE" if "Delete" in url else "UPDATE" if "Update" in url else "SEND"
            transaction_id = find_value(payload, "transactionId") or ""
            with app.connect() as connection:
                row = connection.execute("SELECT cidr FROM cst_transaction_ledger WHERE transaction_id = ?", (transaction_id,)).fetchone()
            status, _error = record(operation, row["cidr"] if row else "", transaction_id, find_value(payload, "assignmentStatusId"))
            return (200 if status == "SUCCESS" else 400), {"accepted": status == "SUCCESS"}

        for name, fake in (("execute_cst_real_api_job", fake_job), ("cst_http_request", fake_http), ("ensure_cst_access_token", lambda *args, **kwargs: "token")):
            self.addCleanup(setattr, app, name, getattr(app, name))
            setattr(app, name, fake)
        with app.connect() as connection:
            # hourly_request_limit only paces real pushes (3600 / limit seconds apart); keep tests fast.
            connection.execute("UPDATE cst_config SET enabled = 1, auto_execute = 1, send_enabled = 1, update_enabled = 1, delete_enabled = 1, hourly_request_limit = 3600000")
            pool = app.pool_from_network(ip_network(ROOT), "Root", "Central")
            app.insert_pool(connection, pool)
            self.root = app.sync_pool_resource(connection, pool)
        self.container_tx = self.cst_record(CONTAINER)

    def tearDown(self):
        app.DB_PATH = self.original_db_path
        shutil.rmtree(self.temp_dir, ignore_errors=True)

    # --- helpers -------------------------------------------------------------------------------
    def cst_record(self, cidr: str, status_id: int = 1) -> str:
        """A record CST already holds (sent earlier, e.g. by the unassigned-space migration)."""
        resource = app.cst_resource_from_network(
            ip_network(cidr), app.stable_uuid("test-record", cidr), app.BULK_UNASSIGNED_FRAGMENT_SOURCE, f"test:{cidr}", "test record"
        ).model_copy(update={"root_pool_uuid": self.root.resource_uuid, "parent_resource_uuid": self.root.resource_uuid, "assignment_status_id": status_id, "cst_sync_ready": True})
        with app.connect() as connection:
            app.upsert_resource_record(connection, resource)
            jobs = app.create_cst_sync_jobs(connection, [(resource, "SEND")], "TEST_SEND")
        self.assertEqual(jobs[0].status, "SUCCESS", jobs[0].last_error)
        self.calls.clear()
        return jobs[0].transaction_id

    def load_assignment(self, cidr: str = ASSIGNED, size: int = 8, customer: str = "Abdul Latif Jameel", allow_conflicts: bool = False):
        result = app.process_assignment_bulk("\n".join([HEADER, business_row(cidr, size, customer, "SVC-1")]), allow_conflicts=allow_conflicts)
        self.assertEqual(result.imported, 1, result.errors)

    def individual_assignment(self, cidr: str, size: int, customer: str = "Walk-in Customer"):
        """Assignment Management path: one assignment, sent to CST straight away."""
        row = next(csv.DictReader(StringIO("\n".join([HEADER, business_row(cidr, size, customer, "SVC-9")]))))
        return app.add_assignment(app.assignment_payload_from_bulk_row(row, ip_network(cidr), 3, "Active", 2))

    def migration_job(self, execute: bool = False) -> app.CstManualMigrationResult:
        result = app.create_manual_cst_migration_job(app.CstManualMigrationRequest(execute_immediately=execute))
        self.assertTrue(result.batch_id, result.message)
        return result

    def batch_jobs(self, batch_id: str) -> list[app.CstSyncJob]:
        with app.connect() as connection:
            return [app.cst_job_from_row(row) for row in connection.execute("SELECT * FROM cst_sync_jobs WHERE batch_id = ? ORDER BY sequence_no", (batch_id,))]

    def chain(self, jobs: list[app.CstSyncJob], head_cidr: str) -> list[app.CstSyncJob]:
        """The partial reassignment chain starting at the job for head_cidr, followed via depends_on_job_id."""
        by_dependency = {job.depends_on_job_id: job for job in jobs if job.depends_on_job_id}
        current = next(job for job in jobs if job.cidr == head_cidr and job.depends_on_job_id.startswith(app.CST_CHAIN_HEAD_PREFIX))
        ordered = [current]
        while current.id in by_dependency:
            current = by_dependency[current.id]
            ordered.append(current)
        return ordered

    def ledger(self, transaction_id: str):
        with app.connect() as connection:
            return connection.execute("SELECT * FROM cst_transaction_ledger WHERE transaction_id = ?", (transaction_id,)).fetchone()

    def ops(self, prefix: str = "87.101.190."):
        return [(op, cidr) for op, cidr, _tx, _status in self.calls if cidr.startswith(prefix)]

    def split_locally(self, assignment, new_cidr: str):
        """The assignment keeps its identity but is cut down locally to new_cidr."""
        network = ip_network(new_cidr)
        with app.connect() as connection:
            connection.execute(
                "UPDATE assignments SET cidr = ?, prefix = ?, size = ?, start = ?, end = ? WHERE id = ?",
                (str(network), network.prefixlen, network.num_addresses, str(network.network_address), str(network.broadcast_address), assignment.id),
            )
            app.sync_assignment_resource(connection, app.assignment_from_row(connection.execute("SELECT * FROM assignments WHERE id = ?", (assignment.id,)).fetchone()))

    def controlled_sync(self):
        with app.connect() as connection:
            connection.execute("UPDATE cst_config SET auto_execute = 0")

    def review(self, scope: str = "all"):
        with app.connect() as connection:
            if scope == "assigned":
                return app.cst_assignment_review_response(connection, app.CstMigrationReviewRequest(page_size=500, resource_scope="assigned")).items
            return app.cst_migration_review_items(connection, app.CstMigrationReviewRequest(page_size=500, resource_scope=scope))

    def create_from_review(self, review_ids, scope: str = "all"):
        return app.create_cst_migration_job_from_review(app.CstMigrationReviewCreateRequest(included_review_ids=review_ids, resource_scope=scope, final_confirmed=True))

    def job_count(self) -> int:
        with app.connect() as connection:
            return connection.execute("SELECT COUNT(*) FROM cst_sync_jobs").fetchone()[0]

    # --- Create Migration Job ------------------------------------------------------------------
    def test_separate_split_endpoint_is_gone(self):
        self.assertNotIn("/cst/container-splits", {route.path for route in app.app.routes})

    def test_migration_job_puts_partial_reassignment_in_one_batch(self):
        self.load_assignment()
        result = self.migration_job()
        jobs = self.batch_jobs(result.batch_id)
        self.assertEqual({job.batch_id for job in jobs}, {result.batch_id})
        chain = self.chain(jobs, CONTAINER)
        self.assertEqual([(job.operation, job.cidr) for job in chain], [("DELETE", CONTAINER), ("SEND", "87.101.190.112/29"), ("SEND", ASSIGNED)])
        self.assertEqual(chain[0].transaction_id, self.container_tx)
        group = next(group for group in result.partial_reassignments if group.container_cidr == CONTAINER)
        self.assertEqual(group.status, "CREATED")
        self.assertEqual(group.operations, [
            f"DeleteLIR {CONTAINER} (Transaction ID {self.container_tx})",
            "SendLIR 87.101.190.112/29 [Unassigned]",
            f"SendLIR {ASSIGNED} [Business]",
        ])
        self.assertEqual(self.calls, [], "queued; CST is called when the job is pushed")

    def test_pushing_the_migration_job_runs_steps_in_order(self):
        self.load_assignment()
        self.migration_job(execute=True)
        operations = self.ops()
        delete_at = operations.index(("DELETE", CONTAINER))
        self.assertLess(delete_at, operations.index(("SEND", "87.101.190.112/29")))
        self.assertLess(delete_at, operations.index(("SEND", ASSIGNED)))
        self.assertNotEqual(self.ledger(self.container_tx)["retired_at"], "")
        self.assertNotIn(self.container_tx, {tx for op, _cidr, tx, _status in self.calls if op == "SEND"})

    def test_failed_step_holds_only_its_own_partial_reassignment(self):
        self.cst_record("87.101.190.32/27")
        self.load_assignment()
        self.load_assignment("87.101.190.32/28", 16, "Second Customer")
        self.reject = {("DELETE", CONTAINER)}
        result = self.migration_job(execute=True)
        jobs = self.batch_jobs(result.batch_id)
        failed_chain = self.chain(jobs, CONTAINER)
        self.assertEqual(failed_chain[0].status, "FAILED")
        self.assertEqual({job.status for job in failed_chain[1:]}, {"PENDING"})
        other_chain = self.chain(jobs, "87.101.190.32/27")
        self.assertEqual({job.status for job in other_chain}, {"SUCCESS"}, "the other partial reassignment is not blocked")
        plain = [job for job in jobs if not job.depends_on_job_id]
        self.assertTrue(plain and all(job.status == "SUCCESS" for job in plain), "plain SendLIRs are not blocked either")

    def test_assigned_record_is_unassigned_then_deleted(self):
        assigned_tx = self.cst_record("87.101.190.32/27", status_id=3)
        self.load_assignment("87.101.190.32/28", 16)
        result = self.migration_job(execute=True)
        group = next(group for group in result.partial_reassignments if group.container_cidr == "87.101.190.32/27")
        self.assertEqual(group.operations, [
            f"UpdateLIR 87.101.190.32/27 to Unassigned (Transaction ID {assigned_tx})",
            f"DeleteLIR 87.101.190.32/27 (Transaction ID {assigned_tx})",
            "SendLIR 87.101.190.32/28 [Business]",
            "SendLIR 87.101.190.48/28 [Unassigned]",
        ])
        steps = [(op, cidr, status) for op, cidr, _tx, status in self.calls if cidr in {"87.101.190.32/27", "87.101.190.32/28", "87.101.190.48/28"}]
        self.assertEqual(steps, [
            ("UPDATE", "87.101.190.32/27", 1), ("DELETE", "87.101.190.32/27", None),
            ("SEND", "87.101.190.32/28", 3), ("SEND", "87.101.190.48/28", 1),
        ])
        self.assertNotEqual(self.ledger(assigned_tx)["retired_at"], "")

    def test_unassigned_record_skips_step_one(self):
        self.load_assignment()
        result = self.migration_job()
        group = next(group for group in result.partial_reassignments if group.container_cidr == CONTAINER)
        self.assertFalse(any(line.startswith("UpdateLIR") for line in group.operations))

    def test_review_shows_partial_reassignment_as_one_row_and_creates_one_batch(self):
        self.load_assignment()
        with app.connect() as connection:
            assignment_resource = app.find_resource_by_cidr(connection, ASSIGNED)
            self.reject = {("SEND", ASSIGNED)}
            failed = app.create_cst_sync_jobs(connection, [(assignment_resource, "SEND")], "MANUAL_LIR_MIGRATION")
        self.assertEqual(failed[0].status, "FAILED")
        self.reject, self.calls = set(), []
        for scope in ("all", "assigned"):
            items = self.review(scope)
            row = next(item for item in items if item.review_id.startswith(app.CST_COMPOSITE_PREFIX) and CONTAINER in item.cidr)
            self.assertEqual(row.composite_type, "Partial reassignment")
            self.assertEqual(row.operation, app.CST_COMPOSITE_PARTIAL)
            self.assertEqual(row.steps, [
                f"DeleteLIR {CONTAINER} (Transaction ID {self.container_tx})",
                "SendLIR 87.101.190.112/29 [Unassigned]",
                f"SendLIR {ASSIGNED} [Business]",
            ])
            self.assertFalse(any(item.cidr in {ASSIGNED, "87.101.190.112/29"} for item in items), "parts are inside the composite row, not separate rows")
        result = self.create_from_review([row.review_id])
        self.assertEqual(result.rejected, [])
        jobs = self.batch_jobs(result.batch_id)
        self.assertEqual({job.batch_id for job in jobs}, {result.batch_id})
        self.assertEqual([(job.operation, job.cidr) for job in self.chain(jobs, CONTAINER)], [("DELETE", CONTAINER), ("SEND", "87.101.190.112/29"), ("SEND", ASSIGNED)])
        self.assertEqual(self.calls, [])

    def test_free_blocks_held_in_cst_are_never_merged(self):
        """No merge of Unassigned blocks CST holds, so no DeleteLIR for them; new free space around them is sent."""
        small_a = self.cst_record("87.101.190.0/30")
        small_b = self.cst_record("87.101.190.4/30")
        self.load_assignment("87.101.190.128/25", 128)
        result = self.migration_job()
        jobs = self.batch_jobs(result.batch_id)
        self.assertFalse([job for job in jobs if job.operation == "DELETE"], [(job.operation, job.cidr) for job in jobs])
        self.assertFalse([group for group in result.partial_reassignments if "87.101.190.0/30" in group.container_cidr])
        with app.connect() as connection:
            cidrs = {row["cidr"] for row in connection.execute("SELECT cidr FROM ip_resources")}
        self.assertTrue({"87.101.190.0/30", "87.101.190.4/30", CONTAINER} <= cidrs)
        self.assertNotIn("87.101.190.0/25", cidrs)
        self.assertEqual(self.ledger(small_a)["retired_at"], "")
        self.assertEqual(self.ledger(small_b)["retired_at"], "")
        sends = {job.cidr for job in jobs if job.operation == "SEND"}
        self.assertIn("87.101.190.8/29", sends, "free space CST does not hold yet is sent as new Unassigned blocks")

    def test_local_split_of_assigned_record(self):
        owner = self.individual_assignment("87.101.190.64/27", 32, "Original Customer")
        old_tx = next(tx for op, cidr, tx, _status in self.calls if op == "SEND" and cidr == "87.101.190.64/27")
        self.calls.clear()
        self.split_locally(owner, "87.101.190.64/28")
        result = self.migration_job(execute=True)
        group = next(group for group in result.partial_reassignments if group.container_cidr == "87.101.190.64/27")
        self.assertEqual(group.operations, [
            f"UpdateLIR 87.101.190.64/27 to Unassigned (Transaction ID {old_tx})",
            f"DeleteLIR 87.101.190.64/27 (Transaction ID {old_tx})",
            "SendLIR 87.101.190.64/28 [Business]",
            "SendLIR 87.101.190.80/28 [Unassigned]",
        ])
        steps = [(op, cidr, status) for op, cidr, _tx, status in self.calls if cidr.startswith("87.101.190.64/") or cidr == "87.101.190.80/28"]
        self.assertEqual(steps[:2], [("UPDATE", "87.101.190.64/27", 1), ("DELETE", "87.101.190.64/27", None)])
        sends = {cidr: tx for op, cidr, tx, _status in self.calls if op == "SEND"}
        self.assertNotIn(old_tx, sends.values(), "the retired Transaction ID is never reused")
        with app.connect() as connection:
            resized = app.find_resource_by_source(connection, "assignment", owner.id)
            self.assertEqual(resized.transaction_id, sends["87.101.190.64/28"])
            self.assertFalse(app.cst_resource_needs_send(connection, resized))

    def test_record_still_assigned_locally_is_blocked(self):
        owner = self.individual_assignment("87.101.190.64/27", 32, "Current Owner")
        self.calls.clear()
        self.load_assignment("87.101.190.64/30", 4, "Other Customer", allow_conflicts=True)
        result = self.migration_job()
        group = next(group for group in result.partial_reassignments if group.container_cidr == owner.cidr)
        self.assertEqual(group.status, "BLOCKED")
        self.assertIn("still assigned locally to Current Owner", group.reason)

