    def test_individual_assignment_inside_cst_record(self):
        self.individual_assignment(ASSIGNED, 8)
        self.assertEqual(self.ops(), [("DELETE", CONTAINER), ("SEND", "87.101.190.112/29"), ("SEND", ASSIGNED)])
        self.assertNotEqual(self.ledger(self.container_tx)["retired_at"], "")

    def test_individual_assignment_also_sends_unsent_bulk_neighbour(self):
        self.load_assignment("87.101.190.112/30", 4)
        self.individual_assignment(ASSIGNED, 8)
        self.assertEqual(self.ops(), [
            ("DELETE", CONTAINER), ("SEND", "87.101.190.112/30"), ("SEND", "87.101.190.116/30"), ("SEND", ASSIGNED),
        ])

    def test_individual_assignment_on_locally_split_record(self):
        owner = self.individual_assignment("87.101.190.64/27", 32, "Original Customer")
        old_tx = next(tx for op, cidr, tx, _status in self.calls if op == "SEND" and cidr == "87.101.190.64/27")
        self.calls.clear()
        self.split_locally(owner, "87.101.190.64/28")
        self.individual_assignment("87.101.190.80/28", 16, "New Customer")
        self.assertEqual([(op, cidr, status) for op, cidr, _tx, status in self.calls], [
            ("UPDATE", "87.101.190.64/27", 1), ("DELETE", "87.101.190.64/27", 1),
            ("SEND", "87.101.190.64/28", 3), ("SEND", "87.101.190.80/28", 3),
        ])
        self.assertEqual([tx for op, _cidr, tx, _status in self.calls if op != "SEND"], [old_tx, old_tx])

    def test_individual_assignment_saved_when_delete_succeeds_but_send_fails(self):
        self.reject = {("SEND", ASSIGNED)}
        with self.assertRaises(app.HTTPException) as raised:
            self.individual_assignment(ASSIGNED, 8)
        self.assertEqual(raised.exception.status_code, 502)
        self.assertIn("Retry failed jobs", raised.exception.detail)
        with app.connect() as connection:
            self.assertIsNotNone(connection.execute("SELECT 1 FROM assignments WHERE cidr = ?", (ASSIGNED,)).fetchone())
        self.assertNotEqual(self.ledger(self.container_tx)["retired_at"], "")

    def test_individual_assignment_rolled_back_when_delete_fails(self):
        self.reject = {("DELETE", CONTAINER)}
        with self.assertRaises(app.HTTPException):
            self.individual_assignment(ASSIGNED, 8)
        with app.connect() as connection:
            self.assertIsNone(connection.execute("SELECT 1 FROM assignments WHERE cidr = ?", (ASSIGNED,)).fetchone())
        self.assertEqual(self.ledger(self.container_tx)["retired_at"], "")

    # --- same CIDR already in CST: UpdateLIR, never a second SendLIR --------------------------
    def last_payload(self, transaction_id: str, operation: str):
        with app.connect() as connection:
            row = connection.execute(
                "SELECT payload_json FROM cst_sync_jobs WHERE transaction_id = ? AND operation = ? ORDER BY created_at DESC LIMIT 1", (transaction_id, operation)
            ).fetchone()
        return json.loads(row["payload_json"])

    def test_assignment_management_on_unassigned_record_sends_update(self):
        self.individual_assignment(CONTAINER, 16, "New Customer")
        self.assertEqual([(op, cidr, tx) for op, cidr, tx, _status in self.calls], [("UPDATE", CONTAINER, self.container_tx)])
        payload = self.last_payload(self.container_tx, "UPDATE")
        self.assertEqual(int(find_value(payload, "assignmentStatusId")), 3)
        self.assertEqual(find_value(payload, "organizationName"), "New Customer")
        self.assertEqual(self.ledger(self.container_tx)["retired_at"], "", "UpdateLIR keeps the Transaction ID")

    def test_bulk_load_on_unassigned_record_is_an_update_row_and_job(self):
        self.load_assignment(CONTAINER, 16, "New Customer")
        for scope in ("all", "assigned"):
            row = next(item for item in self.review(scope) if item.cidr == CONTAINER)
            self.assertEqual(row.operation, "UPDATE")
            self.assertEqual(row.transaction_id, self.container_tx)
        result = self.create_from_review([row.review_id])
        jobs = [job for job in self.batch_jobs(result.batch_id) if job.cidr == CONTAINER]
        self.assertEqual([(job.operation, job.transaction_id) for job in jobs], [("UPDATE", self.container_tx)])
        with app.connect() as connection:
            app.process_cst_batch_pending_jobs(connection, result.batch_id)
        self.assertEqual([op for op, cidr, *_ in self.calls if cidr == CONTAINER], ["UPDATE"])
        self.assertFalse(any(item.cidr == CONTAINER for item in self.review()), "in sync after the UpdateLIR")

    def test_release_then_new_customer_on_same_subnet(self):
        """Termination: UpdateLIR to Unassigned (ID kept); new customer on the same CIDR: UpdateLIR of that ID."""
        first = self.individual_assignment("87.101.190.64/27", 32, "Old Customer")
        tx = next(tx for op, cidr, tx, _status in self.calls if op == "SEND" and cidr == "87.101.190.64/27")
        self.calls.clear()
        app.unassign(first.id)
        self.assertEqual([(op, cidr, t, status) for op, cidr, t, status in self.calls], [("UPDATE", "87.101.190.64/27", tx, 1)])
        self.assertEqual(self.ledger(tx)["retired_at"], "")
        self.assertEqual(self.migration_job_or_none(), [], "nothing left to send for the released block")
        self.calls.clear()
        self.individual_assignment("87.101.190.64/27", 32, "New Customer")
        self.assertEqual([(op, cidr, t, status) for op, cidr, t, status in self.calls], [("UPDATE", "87.101.190.64/27", tx, 3)])
        self.assertEqual(find_value(self.last_payload(tx, "UPDATE"), "organizationName"), "New Customer")

    def test_released_block_fully_free_is_simply_assigned(self):
        """Whole free CST record assigned with the same CIDR: one UpdateLIR, nothing deleted or added."""
        first = self.individual_assignment("87.101.190.64/27", 32, "Old Customer")
        tx = next(t for op, cidr, t, _status in self.calls if op == "SEND" and cidr == "87.101.190.64/27")
        app.unassign(first.id)
        self.calls.clear()
        self.individual_assignment("87.101.190.64/27", 32, "New Customer")
        self.assertEqual([(op, cidr, t, status) for op, cidr, t, status in self.calls], [("UPDATE", "87.101.190.64/27", tx, 3)])

    def test_released_block_partly_assigned_follows_partial_reassignment_rule(self):
        """Part of a free CST record assigned: step 1 skipped (already Unassigned), DeleteLIR, SendLIR x2."""
        first = self.individual_assignment("87.101.190.64/27", 32, "Old Customer")
        tx = next(t for op, cidr, t, _status in self.calls if op == "SEND" and cidr == "87.101.190.64/27")
        app.unassign(first.id)
        self.calls.clear()
        self.individual_assignment("87.101.190.64/28", 16, "New Customer")
        self.assertEqual([(op, cidr) for op, cidr, _t, _status in self.calls], [
            ("DELETE", "87.101.190.64/27"), ("SEND", "87.101.190.64/28"), ("SEND", "87.101.190.80/28"),
        ])
        self.assertEqual([status for op, _cidr, _t, status in self.calls if op == "SEND"], [3, 1])
        self.assertEqual(self.calls[0][2], tx)
        self.assertNotIn(tx, [t for op, _cidr, t, _status in self.calls[1:]], "new records get new Transaction IDs")
        self.assertNotEqual(self.ledger(tx)["retired_at"], "")

    def test_update_lir_sends_the_complete_record_on_the_same_transaction(self):
        first = self.individual_assignment("87.101.190.64/27", 32, "Old Customer")
        tx = next(t for op, cidr, t, _status in self.calls if op == "SEND" and cidr == "87.101.190.64/27")
        app.unassign(first.id)
        prohibited = {"serviceProviderId", "ipSubnet", "asn", "ipVersionId"}  # CST LIR 3.2: cannot be changed
        unassign_request = self.last_payload(tx, "UPDATE")
        unassign = unassign_request["data"][0]
        self.assertEqual((unassign["transactionId"], unassign["assignmentStatusId"]), (tx, 1))
        self.assertFalse(prohibited & set(unassign), "prohibited fields are not sent")
        self.assertIn("serviceProviderId", unassign_request, "provider stays at request level")
        self.assertFalse({"organizationName", "organizationId", "contact", "customerTypeId"} & set(unassign), "no customer data left on unassign")
        self.individual_assignment("87.101.190.64/27", 32, "New Customer")
        assign = self.last_payload(tx, "UPDATE")["data"][0]
        self.assertEqual((assign["transactionId"], assign["assignmentStatusId"], assign["organizationName"]), (tx, 3, "New Customer"))
        self.assertFalse(prohibited & set(assign))
        self.assertTrue({"organizationId", "customerTypeId", "regionId", "cityId", "contact", "assignmentDate", "updateDate", "serviceDescription"} <= set(assign))

